CREATE TABLE dictionary_item (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    created_at TIMESTAMP NOT NULL,
    updated_at TIMESTAMP NOT NULL,
    type VARCHAR(50) NOT NULL,
    label VARCHAR(255) NOT NULL,
    active BOOLEAN NOT NULL DEFAULT 1,
    allowed_role VARCHAR(50),
    CONSTRAINT uk_dictionary_type_label UNIQUE (type, label)
);

CREATE INDEX idx_dict_type ON dictionary_item (type);
CREATE INDEX idx_dict_active ON dictionary_item (active);
CREATE INDEX idx_dict_role ON dictionary_item (allowed_role);
CREATE INDEX idx_dict_label ON dictionary_item (label);
